Audit this Node.js Express code snippet for security risks:

```javascript
const express = require('express');
const { exec } = require('child_process');
const app = express();

app.get('/ping', (req, res) => {
  const host = req.query.host;
  exec(`ping -c 3 ${host}`, (err, stdout, stderr) => {
    if (err) return res.status(500).send(stderr);
    res.send(stdout);
  });
});
```

### Security Assessment by Fluxnat Coder 3B

**Severity:** Critical (CVSS 9.8)
**Vulnerability:** OS Command Injection
**CWE:** CWE-78 (Improper Neutralization of Special Elements used in an OS Command)
**OWASP:** A03:2021 - Injection

#### Root Cause & Step-by-Step Reasoning:
1. **Untrusted Input:** `req.query.host` is ingested directly from the HTTP query string.
2. **Shell Evaluation:** `child_process.exec()` invokes an underlying system shell (`/bin/sh` or `cmd.exe`).
3. **Metacharacter Exploitation:** Attackers can append command separators (`;`, `&`, `|`, `` ` ``) such as `8.8.8.8; cat /etc/passwd` to execute arbitrary commands with host privileges.

#### Secure Remediation:
Replace `exec` with `execFile`, pass arguments as a separated array, and strictly validate the input pattern.

```javascript
const express = require('express');
const { execFile } = require('child_process');
const net = require('net');
const app = express();

app.get('/ping', (req, res) => {
  const host = req.query.host;
  if (!host || (!net.isIP(host) && !/^[a-zA-Z0-9.-]+$/.test(host))) {
    return res.status(400).json({ error: 'Invalid hostname or IP format' });
  }
  execFile('ping', ['-c', '3', host], { timeout: 5000 }, (err, stdout, stderr) => {
    if (err) return res.status(500).json({ error: 'Ping failed' });
    res.type('text/plain').send(stdout);
  });
});
```

